import React, { useEffect, useState } from 'react';
import { Link, useParams } from 'react-router-dom';
import {
  AlertTriangle,
  ArrowLeft,
  Box,
  CheckCircle2,
  Loader2,
  LockKeyhole,
  ScanLine,
  ShieldCheck,
  Truck,
} from 'lucide-react';
import { useAuth } from '../context/AuthContext';
import { trustCenterAction, TrustCenterError } from '../lib/trustCenter';
import { formatOrderMoney } from '../lib/physicalFulfillment';

type PackageDetails = {
  orderId: string;
  publicCode: string;
  listing?: { title?: string; images?: string[]; image_url?: string; thumbnail?: string };
  seller?: { full_name?: string; username?: string } | null;
  shipment?: { status?: string; carrier?: string; tracking_number?: string; shipped_at?: string; estimated_delivery_at?: string } | null;
  reserve?: { amount_total?: number; currency?: string; status?: string } | null;
  dispute?: { id?: string; status?: string; reason?: string } | null;
};

const field = 'w-full rounded-2xl border border-white/10 bg-black/40 px-4 py-3 text-sm text-white outline-none focus:border-white/30';

export default function PackageConfirmation() {
  const { publicCode = '', token = '' } = useParams();
  const { user } = useAuth();
  const [details, setDetails] = useState<PackageDetails | null>(null);
  const [loading, setLoading] = useState(Boolean(user));
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  const [confirmed, setConfirmed] = useState(false);
  const [releaseStatus, setReleaseStatus] = useState('');
  const [declaration, setDeclaration] = useState(false);
  const [note, setNote] = useState('');
  const [reporting, setReporting] = useState(false);
  const [reason, setReason] = useState('damaged_product');
  const [description, setDescription] = useState('');

  useEffect(() => {
    if (!user) return;
    let cancelled = false;
    setLoading(true);
    trustCenterAction<{ package: PackageDetails }>('physical-order-details', { publicCode, token })
      .then((result) => { if (!cancelled) setDetails(result.package); })
      .catch((loadError) => { if (!cancelled) setError(loadError instanceof TrustCenterError ? loadError.message : 'This package link could not be verified.'); })
      .finally(() => { if (!cancelled) setLoading(false); });
    return () => { cancelled = true; };
  }, [publicCode, token, user]);

  const confirm = async () => {
    if (!declaration) return;
    setBusy(true);
    setError('');
    try {
      const result = await trustCenterAction<{ confirmation: { confirmed_at: string }; release: { status: string } }>('confirm-physical-delivery', { publicCode, token, note });
      setReleaseStatus(result.release?.status || 'release_pending');
      setConfirmed(true);
    } catch (confirmError) {
      setError(confirmError instanceof Error ? confirmError.message : 'Delivery could not be confirmed.');
    } finally { setBusy(false); }
  };

  const report = async () => {
    if (!details?.orderId || description.trim().length < 10) return;
    setBusy(true);
    setError('');
    try {
      await trustCenterAction('open-physical-dispute', { orderId: details.orderId, reason, description });
      setDetails((current) => current ? { ...current, dispute: { status: 'open', reason } } : current);
      setReporting(false);
    } catch (reportError) {
      setError(reportError instanceof Error ? reportError.message : 'The protected case could not be opened.');
    } finally { setBusy(false); }
  };

  if (!user) {
    const returnPath = `/package/confirm/${encodeURIComponent(publicCode)}/${encodeURIComponent(token)}`;
    return (
      <main className="grid min-h-screen place-items-center bg-black px-5 text-white">
        <div className="w-full max-w-md rounded-[30px] border border-white/10 bg-[#111] p-7 text-center">
          <div className="mx-auto grid h-14 w-14 place-items-center rounded-2xl bg-blue-500/10 text-blue-300"><ScanLine className="h-7 w-7" /></div>
          <p className="mt-5 text-xs font-semibold uppercase tracking-[0.18em] text-blue-300">Secure package check</p>
          <h1 className="mt-2 text-2xl font-semibold">Sign in as the buyer</h1>
          <p className="mt-3 text-sm leading-6 text-gray-400">Wersee never confirms delivery from a scan alone. Sign in to prove that you are the buyer linked to this order.</p>
          <Link to={`/signin?redirect=${encodeURIComponent(returnPath)}`} className="mt-6 inline-flex w-full items-center justify-center rounded-2xl bg-white px-5 py-3.5 text-sm font-semibold text-black">Sign in to review package</Link>
          <p className="mt-4 text-xs text-gray-600">Do not share this private QR link.</p>
        </div>
      </main>
    );
  }

  if (loading) return <main className="grid min-h-screen place-items-center bg-black text-white"><div className="text-center"><Loader2 className="mx-auto h-7 w-7 animate-spin text-blue-300" /><p className="mt-3 text-sm text-gray-500">Verifying package and buyer…</p></div></main>;

  if (error && !details) return (
    <main className="grid min-h-screen place-items-center bg-black px-5 text-white"><div className="w-full max-w-md rounded-[30px] border border-red-500/20 bg-[#111] p-7 text-center"><AlertTriangle className="mx-auto h-8 w-8 text-red-300" /><h1 className="mt-4 text-xl font-semibold">Package link unavailable</h1><p className="mt-3 text-sm leading-6 text-gray-400">{error}</p><Link to="/workspace/management/orders" className="mt-6 inline-flex items-center gap-2 text-sm font-semibold text-white"><ArrowLeft className="h-4 w-4" />View my orders</Link></div></main>
  );

  if (confirmed) return (
    <main className="grid min-h-screen place-items-center bg-black px-5 text-white"><div className="w-full max-w-lg rounded-[30px] border border-emerald-500/20 bg-[#111] p-8 text-center"><CheckCircle2 className="mx-auto h-12 w-12 text-emerald-300" /><p className="mt-5 text-xs font-semibold uppercase tracking-[0.18em] text-emerald-300">Delivery recorded</p><h1 className="mt-2 text-2xl font-semibold">Thank you for confirming</h1><p className="mt-3 text-sm leading-6 text-gray-400">The fulfillment audit trail has been updated. {releaseStatus === 'released' ? 'The protected seller amount was released through Stripe.' : 'The provider transfer is still protected and will be retried or reviewed; it was not falsely marked as paid out.'}</p><Link to="/workspace/management/orders" className="mt-6 inline-flex rounded-2xl bg-white px-5 py-3 text-sm font-semibold text-black">View order</Link></div></main>
  );

  const image = details?.listing?.images?.[0] || details?.listing?.image_url || details?.listing?.thumbnail;
  return (
    <main className="min-h-screen bg-black px-4 py-8 text-white sm:px-6">
      <div className="mx-auto max-w-3xl">
        <div className="mb-6 flex items-center justify-between"><Link to="/workspace/management/orders" className="inline-flex items-center gap-2 text-sm text-gray-400 hover:text-white"><ArrowLeft className="h-4 w-4" />My orders</Link><div className="flex items-center gap-2 text-xs font-semibold text-emerald-300"><ShieldCheck className="h-4 w-4" />Authenticated buyer</div></div>
        <div className="overflow-hidden rounded-[32px] border border-white/10 bg-[#0f0f0f]">
          <div className="border-b border-white/10 p-6 sm:p-8"><p className="text-xs font-semibold uppercase tracking-[0.2em] text-blue-300">Package {details?.publicCode}</p><h1 className="mt-2 text-3xl font-semibold tracking-tight">Check before you confirm</h1><p className="mt-3 max-w-xl text-sm leading-6 text-gray-400">Only confirm after opening the package and checking the product. A problem report keeps the Payment Reserve on hold.</p></div>
          <div className="grid gap-6 p-6 sm:p-8 md:grid-cols-[150px_1fr]">
            <div className="aspect-square overflow-hidden rounded-3xl border border-white/10 bg-white/[0.03]">{image ? <img src={image} alt="" className="h-full w-full object-cover" /> : <div className="grid h-full place-items-center"><Box className="h-8 w-8 text-gray-600" /></div>}</div>
            <div><h2 className="text-xl font-semibold">{details?.listing?.title || 'Physical product'}</h2><p className="mt-1 text-sm text-gray-500">Sold by {details?.seller?.full_name || details?.seller?.username || 'Wersee seller'}</p><div className="mt-5 grid gap-3 sm:grid-cols-2"><div className="rounded-2xl border border-white/10 p-4"><Truck className="h-4 w-4 text-violet-300" /><p className="mt-2 text-xs text-gray-500">Shipment</p><p className="mt-1 text-sm font-medium">{details?.shipment?.carrier || 'Carrier not set'}{details?.shipment?.tracking_number ? ` · ${details.shipment.tracking_number}` : ''}</p></div><div className="rounded-2xl border border-emerald-500/15 bg-emerald-500/[0.05] p-4"><LockKeyhole className="h-4 w-4 text-emerald-300" /><p className="mt-2 text-xs text-gray-500">Payment Reserve</p><p className="mt-1 text-sm font-medium">{formatOrderMoney(details?.reserve?.amount_total, details?.reserve?.currency)} · {details?.reserve?.status}</p></div></div></div>
          </div>

          {details?.dispute ? <div className="m-6 mt-0 rounded-2xl border border-red-500/20 bg-red-500/[0.07] p-5 sm:m-8 sm:mt-0"><h2 className="font-semibold text-red-200">Problem report is open</h2><p className="mt-2 text-sm leading-6 text-gray-400">The Payment Reserve remains on hold. Delivery cannot be confirmed until this case is resolved.</p></div> : reporting ? <div className="m-6 mt-0 space-y-4 rounded-2xl border border-red-500/20 bg-red-500/[0.04] p-5 sm:m-8 sm:mt-0"><h2 className="font-semibold">Report a problem instead</h2><label className="block text-xs text-gray-400">Reason<select value={reason} onChange={(e) => setReason(e.target.value)} className={`${field} mt-2`}><option value="damaged_product">Product is damaged</option><option value="wrong_product">Wrong product</option><option value="empty_box">Empty package</option><option value="fake_product">Suspected counterfeit</option><option value="missing_qr">QR problem</option><option value="seller_pressure">Seller asked me to confirm early</option><option value="tracking_issue">Tracking issue</option><option value="not_received">Package not received</option><option value="other">Other</option></select></label><label className="block text-xs text-gray-400">What happened?<textarea value={description} onChange={(e) => setDescription(e.target.value)} className={`${field} mt-2 min-h-28 resize-y`} /></label><div className="flex gap-3"><button onClick={() => setReporting(false)} className="flex-1 rounded-2xl border border-white/10 px-4 py-3 text-sm font-semibold">Cancel</button><button onClick={report} disabled={busy || description.trim().length < 10} className="flex-1 rounded-2xl bg-red-500 px-4 py-3 text-sm font-semibold disabled:opacity-40">{busy ? 'Opening…' : 'Open case'}</button></div></div> : <div className="border-t border-white/10 p-6 sm:p-8">
            {error && <div className="mb-4 flex gap-3 rounded-2xl border border-red-500/20 bg-red-500/[0.06] p-4 text-sm text-red-200"><AlertTriangle className="mt-0.5 h-4 w-4 shrink-0" />{error}</div>}
            <label className="block text-xs text-gray-400">Optional note<textarea value={note} onChange={(e) => setNote(e.target.value)} className={`${field} mt-2 min-h-20 resize-y`} placeholder="Package condition or a short delivery note" /></label>
            <label className="mt-4 flex cursor-pointer items-start gap-3 rounded-2xl border border-white/10 p-4"><input type="checkbox" checked={declaration} onChange={(e) => setDeclaration(e.target.checked)} className="mt-0.5 h-4 w-4 accent-white" /><span className="text-sm leading-6 text-gray-300"><strong className="block text-white">I physically received and checked this order.</strong>I understand this explicit confirmation starts the seller-transfer release. I am not confirming from a screenshot, message or seller request.</span></label>
            <div className="mt-5 grid gap-3 sm:grid-cols-2"><button onClick={() => setReporting(true)} className="inline-flex items-center justify-center gap-2 rounded-2xl border border-red-500/25 px-5 py-3.5 text-sm font-semibold text-red-200"><AlertTriangle className="h-4 w-4" />Report a problem</button><button onClick={confirm} disabled={busy || !declaration} className="inline-flex items-center justify-center gap-2 rounded-2xl bg-white px-5 py-3.5 text-sm font-semibold text-black disabled:opacity-40">{busy ? <Loader2 className="h-4 w-4 animate-spin" /> : <CheckCircle2 className="h-4 w-4" />}Confirm received</button></div>
          </div>}
        </div>
        <p className="mx-auto mt-5 max-w-xl text-center text-xs leading-5 text-gray-600">Wersee stores a hashed one-time QR token, buyer identity, timestamp and device/IP hashes for fraud prevention and dispute evidence. The raw QR secret is not stored.</p>
      </div>
    </main>
  );
}
